using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public class RepairFake:KokoroEngine {
 public int Calls;public double Seconds=4.12;public string Fail="";
 public override void CheckFiles(){}public override Wave Generate(string text,double speed,string path){Calls++;if(text.Contains(Fail)&&Fail.Length>0)throw new Exception("simulated synthesis failure");if(Cancelled)throw new OperationCanceledException();return Signal(Seconds,Speaker==1?.08:.057);}
 public static Wave Signal(double seconds,double frequency=.057){int n=(int)Math.Round(seconds*24000);var samples=new short[n];for(int i=0;i<n-120;i++)samples[i]=(short)(7000*Math.Sin(i*frequency));return new Wave{Rate=24000,Samples=samples};}
}
public static class AudioRepairTests {
 static int n;static void Check(bool b,string name){if(!b)throw new Exception(name);Console.WriteLine("PASS "+name);n++;}static void Reject(Action a,string name){try{a();}catch{Check(true,name);return;}throw new Exception(name);}
 public static VoiceSettings Settings(){return new VoiceSettings{Key="K:0",Mode=0,Speed=1,MinSpeed=.9,MaxSpeed=1.1,GentleFit=true,Normalize=false,Breathing=2,Punctuation=1,CommaPause=0,StopPause=0,QuestionPause=0,ParagraphPause=0};}
 public static List<Cue> Cues(){return new List<Cue>{new Cue{Id=1,Start=.2,End=4.2,Text="First story stays here."},new Cue{Id=2,Start=4.4,End=8.4,Text="Second story stays here."},new Cue{Id=3,Start=8.6,End=12.6,Text="Third story stays here."}};}
 public static void Main(){string d=Path.Combine(Path.GetTempPath(),"V15 A-B giọng "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);var cues=Cues();string source=Path.Combine(d,"truyện.srt");File.WriteAllText(source,Scripts.ToSrt(cues));string sourceHash=StateFiles.Hash(source),xml=Settings().Xml().ToString();var p=RepairSession.Open(source,cues,d,false);p.Settings=xml;p.Save();Check(p.Parts.Count==3,"Locked SRT uses one cue per repair interval");p=RepairSession.Open(source,cues,d,false);Check(p.Parts.All(s=>s.Selected==null&&s.A==null&&s.B==null),"Empty serialized candidates restore as null");
 var a=new RepairFake{Root=d,VoiceName="A",Speaker=0};var b=new RepairFake{Root=d,VoiceName="B",Speaker=1,Seconds=3.1};var o=AudioRepair.Options(xml);
 var ta=AudioRepair.Trial(p,p.Parts[1],a,o,"K:0",VoiceRenderReport.Snapshot(p.Parts[1].Stage.Cues),"A");Check(ta.Success&&ta.Natural>4&&ta.Speed<=1.100001,"A measures real audio then fits within maximum speed");var tb=AudioRepair.Trial(p,p.Parts[1],b,AudioRepair.Options(xml),"K:1",VoiceRenderReport.Snapshot(p.Parts[1].Stage.Cues),"B");Check(tb.Success&&tb.Tail>.4,"Short B retains explicit bounded tail silence");Check(ta.Audio!=tb.Audio&&StateFiles.Hash(ta.Audio)==ta.Hash,"A and B audio files remain independent");Check(tb.SpeechSeconds+tb.Tail>=3.999&&FinalAudio.PcmFrames(tb.Audio)==96000,"Speech end and tail distinguish padded window duration");Check(tb.Cues[0].Id==2,"Selected cue keeps original ID in trial and report");Check(File.Exists(p.Report)&&File.ReadAllText(p.Report).Contains("ĐO A/B"),"Trial report is written without final output");Check(p.Output.Length==0&&!p.Parts[1].HasAudio,"Trial never replaces adopted/background audio");
 Check(AudioRepair.Matches(tb,b,AudioRepair.Options(xml),p.Parts[1].Stage.Cues),"Matching selected voice and words validates B");var changed=VoiceRenderReport.Snapshot(p.Parts[1].Stage.Cues);changed[0].Text="Different words here.";Check(!AudioRepair.Matches(tb,b,AudioRepair.Options(xml),changed),"Editing words invalidates stale B");Check(!AudioRepair.Matches(tb,a,AudioRepair.Options(xml),p.Parts[1].Stage.Cues),"Switching voice invalidates stale B");var option=AudioRepair.Options(xml);option.CommaPause=.2;Check(!AudioRepair.Matches(tb,b,option,p.Parts[1].Stage.Cues),"Changing pauses invalidates old comparison");
 var noSlow=AudioRepair.Options(xml);noSlow.SlowShort=false;var noSlowTake=AudioRepair.Trial(p,p.Parts[0],b,noSlow,"K:1",p.Parts[0].Stage.Cues,"B");Check(noSlowTake.Success&&Math.Abs(noSlowTake.Speed-1)<.001&&noSlowTake.Tail>.8,"Disabling short-phrase slowdown retains base speed and explicit tail");
 var overflow=new RepairFake{Root=d,VoiceName="long",Seconds=6.5};var bad=AudioRepair.Trial(p,p.Parts[0],overflow,AudioRepair.Options(xml),"long",p.Parts[0].Stage.Cues,"A");Check(!bad.Success&&File.Exists(bad.Audio)&&bad.Measured>4,"Overflow candidate remains listenable but cannot be merged");p.Parts[0].Selected=bad;Reject(()=>AudioRepair.Merge(p,a,AudioRepair.Options(xml),(i,m)=>{}),"Merge rejects overflow without publishing WAV");p.Parts[0].Selected=null;
 p.Parts[1].Selected=tb;int beforeB=b.Calls;string output=AudioRepair.Merge(p,a,AudioRepair.Options(xml),(i,m)=>{});Check(p.Effective().Select(c=>c.Id).SequenceEqual(new[]{1,2,3}),"Auto-created background intervals preserve absolute cue IDs");Check(File.Exists(output)&&FinalAudio.PcmFrames(output)==302400,"Merge produces exact source total frames including gaps and lead silence");Check(b.Calls==beforeB&&a.Calls==3,"Adoption uses exact B; only two missing background parts synthesize");var whole=Wave.Read(output);var bw=Wave.Read(tb.Audio);Check(whole.Samples.Skip((int)(4.4*24000)).Take(bw.Samples.Length).SequenceEqual(bw.Samples),"Merged selected interval is the exact listened B waveform");Check(whole.Samples.Take(4800).All(s=>s==0),"Leading source silence remains intact");Check(File.ReadAllText(p.Report).Contains("Giọng: B")&&File.ReadAllText(p.Report).Contains("Lời gốc"),"Final report records mixed voices, original text and per-stage metrics");Check(StateFiles.Hash(source)==sourceHash,"Source SRT is never overwritten");
 p=RepairSession.Open(source,cues,d,false);Check(p.Parts[1].Selected.Voice=="B"&&p.Output==output,"Chosen voice, text, candidates and output survive reopen");string first=p.Parts[0].Selected.Audio,firstHash=StateFiles.Hash(first);var replacement=VoiceRenderReport.Snapshot(p.Parts[1].Stage.Cues);replacement[0].Text="Revised second story here.";ta=AudioRepair.Trial(p,p.Parts[1],a,AudioRepair.Options(xml),"K:0",replacement,"A");p.Parts[1].Selected=ta;string next=AudioRepair.Merge(p,a,AudioRepair.Options(xml),(i,m)=>{});Check(next!=output&&File.Exists(output),"Publishing repair keeps previous complete WAV");Check(StateFiles.Hash(first)==firstHash&&Wave.Read(next).Samples.Take(100800).SequenceEqual(whole.Samples.Take(100800)),"Other successful parts and samples stay unchanged without normalization");Check(p.Effective()[1].Text==replacement[0].Text&&p.Effective()[1].Start==4.4,"Edited text retains source timecodes in separate effective SRT");
 var publishedWords=Scripts.ToSrt(p.PublishedCues);File.AppendAllText(ta.Audio,"corrupt");Reject(()=>AudioRepair.Merge(p,a,AudioRepair.Options(xml),(i,m)=>{}),"Corrupt adopted audio is rejected without silently replacing chosen take");Check(File.Exists(next)&&Scripts.ToSrt(p.PublishedCues)==publishedWords,"Failed merge preserves last published WAV and text snapshot");
 var anchoredCues=Cues();var anchored=RepairSession.Open(source,anchoredCues,d,true);anchored.Settings=new VoiceSettings{Key="K:0",Mode=2,Normalize=false,Breathing=2}.Xml().ToString();Check(anchored.Parts.Count==1&&anchored.At(1).Stage.Cues.Count==3,"V15.6 repair scope exposes whole grouped stage");
 var groupedWords=VoiceRenderReport.Snapshot(anchored.Sources);groupedWords[1].Text="Revised middle sentence.";var groupTake=AudioRepair.Trial(anchored,anchored.Parts[0],a,AudioRepair.Options(anchored.Settings),"K:0",groupedWords,"A");Check(groupTake.Success&&groupTake.Cues.Count==3&&groupTake.Cues[1].Text==groupedWords[1].Text,"V15.6 renders the full announced group while editing only selected cue");anchored.Parts[0].Selected=groupTake;var groupWav=AudioRepair.Merge(anchored,a,AudioRepair.Options(anchored.Settings),(i,m)=>{});Check(FinalAudio.PcmFrames(groupWav)==302400&&anchored.Effective()[0].Text==cues[0].Text&&anchored.Effective()[2].Text==cues[2].Text,"Grouped adoption retains total timeline and other cue words");Check(anchored.Effective().Select(c=>c.Id).SequenceEqual(new[]{1,2,3}),"Grouped adoption preserves source cue IDs");
 string baseline=Path.Combine(d,"baseline.wav");using(var w=new StreamingWave(baseline,24000)){w.At(.2,RepairFake.Signal(12.4));w.Finish(12.6);}RepairSession.Capture(source,cues,d,false,xml,a,AudioRepair.Options(xml),baseline);p=RepairSession.Open(source,cues,d,false);Check(p.Parts.All(s=>s.HasAudio&&s.Selected==null),"Normal render snapshot captures all measured PCM windows");beforeB=a.Calls;AudioRepair.Merge(p,a,AudioRepair.Options(xml),(i,m)=>{});Check(a.Calls==beforeB,"Captured baseline merges without regenerating other sentences");p.Parts[1].Audio=Path.Combine(p.Folder,"missing.wav");p.Save();AudioRepair.Merge(p,a,AudioRepair.Options(xml),(i,m)=>{});Check(a.Calls==beforeB+1,"Missing background cache regenerates only missing interval");
 var cancelled=new RepairFake{Root=d,VoiceName="A",Cancelled=true};Reject(()=>AudioRepair.Trial(p,p.Parts[0],cancelled,AudioRepair.Options(xml),"K:0",p.Parts[0].Stage.Cues,"A"),"Cancellation is reported and does not apply trial");Check(File.ReadAllText(p.Report).Contains("ĐÃ DỪNG"),"Cancelled trial has a report");
 var fail=new RepairFake{Root=d,VoiceName="fail",Fail="First"};Reject(()=>AudioRepair.Trial(p,p.Parts[0],fail,AudioRepair.Options(xml),"K:0",p.Parts[0].Stage.Cues,"A"),"TTS error propagates for visible retry");Check(File.ReadAllText(p.Report).Contains("simulated synthesis failure"),"Synthesis failure is included in report");
 string normSource=Path.Combine(d,"normalized.srt");File.WriteAllText(normSource,Scripts.ToSrt(Cues()));var normProject=RepairSession.Open(normSource,Cues(),d,false);var normSettings=Settings();normSettings.Normalize=true;normProject.Settings=normSettings.Xml().ToString();var normalized=AudioRepair.Merge(normProject,a,AudioRepair.Options(normProject.Settings),(i,m)=>{});Check(FinalAudio.PcmFrames(normalized)==302400&&File.ReadAllText(normProject.Report).Contains("Cân âm tổng"),"Whole-file normalization preserves duration and is disclosed in report");
 File.AppendAllText(source,"\nCHANGED");Reject(()=>AudioRepair.Merge(p,a,AudioRepair.Options(xml),(i,m)=>{}),"Externally changed source cannot receive old edits");Check(File.ReadAllText(p.Report).Contains("THẤT BẠI"),"Changed-source merge writes failure report");Check(!Directory.GetFiles(p.Folder,"merge-*.wav").Any()&&!Directory.GetDirectories(p.Folder,"work-*").Any(),"Failed or cancelled operations leave no intermediate merge/work files");var job=BatchJob.Load(normSource);job.RepairMode=2;string queue=Path.Combine(d,"repair-queue.xml");QueueStore.Save(queue,new[]{job});Check(QueueStore.Load(queue).Single().RepairMode==2,"Queue persists actual V15.6 render mode for A/B scope after reopening");Console.WriteLine("TOTAL AUDIO REPAIR "+n+" passed.");}
}
